function fusionarIntervalos(intervalos) {
  const ord = [...intervalos].sort((a, b) => a[0] - b[0]);
  const res = [];
  for (const [ini, fin] of ord) {
    const ult = res.at(-1);
    if (ult && ini <= ult[1]) ult[1] = Math.max(ult[1], fin);
    else res.push([ini, fin]);
  }
  return res;
}

